#include "PluginProcessor.h"
#include "CurrentUiChecks.h"
#include <iostream>
#include <complex>
int failures=0;
void check(bool ok,const char* message){std::cout<<(ok?"PASS ":"FAIL ")<<message<<std::endl;if(!ok)++failures;}
struct Listener:juce::AudioProcessorParameter::Listener{int begin=0,end=0,values=0;void parameterValueChanged(int,float)override{++values;}void parameterGestureChanged(int,bool starting)override{starting?++begin:++end;}};
juce::MouseEvent mouse(juce::Component& c,juce::Point<float> pt,bool drag=false){const auto now=juce::Time::getCurrentTime();return {juce::Desktop::getInstance().getMainMouseSource(),pt,juce::ModifierKeys::leftButtonModifier,1,0,0,0,0,&c,&c,now,pt,now,1,drag};}
void tick(){juce::Thread::sleep(50);juce::Timer::callPendingTimersSynchronously();}
double tone(GillEffectProcessor& p,double hz){juce::MidiBuffer midi;juce::AudioBuffer<float>b(2,256);double input=0,output=0;for(int block=0;block<120;++block){for(int i=0;i<256;++i){float x=.1f*float(std::sin(juce::MathConstants<double>::twoPi*hz*(block*256+i)/48000));b.setSample(0,i,x);b.setSample(1,i,x);if(block>80)input+=x*x;}p.processBlock(b,midi);if(block>80)for(int i=0;i<256;++i)output+=b.getSample(0,i)*b.getSample(0,i);}return 10*std::log10(output/input);}
double measuredResponse(const BalanceView& v,double hz){const auto z=std::polar(1.,-juce::MathConstants<double>::twoPi*hz/48000);auto chain=[&](const auto& cs){std::complex<double> h=1;for(auto c:cs)h*=(c[0]+c[1]*z+c[2]*z*z)/(1.+c[3]*z+c[4]*z*z);return h;};auto fine=chain(v.fine.coefficients)*v.fine.transitionBlend+chain(v.fine.previousCoefficients)*(1-v.fine.transitionBlend);return 20*std::log10(std::abs(chain(v.coefficients)*(1.+(fine-1.)*v.fine.wetBlend)));}
int main(){juce::ScopedJuceInitialiser_GUI init;GillEffectProcessor p(GillKind::Balance);p.prepareToPlay(48000,256);check(std::abs(tone(p,800))<.001,"Default trim is transparent");std::unique_ptr<juce::AudioProcessorEditor> editor(p.createEditor());editor->addToDesktop(0);editor->setVisible(true);tick();gillCurrentUi::verify(editor.get(),p.getName(),check);juce::Component* graph=nullptr;for(auto* c:editor->getChildren())if(c->getName()=="BALANCE EQ GRAPH")graph=c;check(graph&&graph->getWidth()==696&&graph->getHeight()==270,"Large native graph present");if(!graph)return 1;
    auto* param=p.apvts.getParameter("trim3");Listener listener;param->addListener(&listener);const float x=46+float(std::log(800./20)/std::log(1000.))*600;graph->mouseDown(mouse(*graph,{x,134}));graph->mouseDrag(mouse(*graph,{x,110},true));graph->mouseUp(mouse(*graph,{x,110}));check(listener.begin==1&&listener.end==1&&listener.values>0,"Graph drag sends balanced host automation gestures");check(p.value("trim3")>4.9f&&p.value("trim3")<5.1f,"Vertical drag changes persistent trim parameter");const double gain=tone(p,800);check(std::abs(gain-p.value("trim3"))<.025,"Native drag alters real audio by the displayed bell gain");check(std::abs(measuredResponse(p.balanceView(),800)-gain)<.025,"Displayed coefficient snapshot matches measured transfer function");tick();
    juce::MemoryBlock state;p.getStateInformation(state);GillEffectProcessor recalled(GillKind::Balance);recalled.setStateInformation(state.getData(),int(state.getSize()));recalled.prepareToPlay(48000,256);check(std::abs(tone(recalled,800)-gain)<.001,"Saved graph trim recalls sample-equivalent response");
    auto legacy=p.apvts.copyState();for(int i=7;i>=0;--i)legacy.removeChild(legacy.getChildWithProperty("id","trim"+juce::String(i)),nullptr);juce::MemoryBlock old;juce::AudioProcessor::copyXmlToBinary(*legacy.createXml(),old);p.setStateInformation(old.getData(),int(old.getSize()));check(p.value("trim3")==0,"Legacy state resets absent trims to zero on edited instance");check(std::abs(tone(p,800))<.001,"Legacy audio remains transparent");
    graph->keyPressed(juce::KeyPress(juce::KeyPress::upKey));check(std::abs(p.value("trim3")-.1f)<.001,"Keyboard graph editing controls gain");graph->mouseDoubleClick(mouse(*graph,{x,134}));check(p.value("trim3")==0,"Double-click resets selected gain");param->removeListener(&listener);
    tone(p,800);tick();editor->setSize(1480,900);tick();const float highX=(46+float(std::log(12000./20)/std::log(1000.))*600)*2;graph->mouseDown(mouse(*graph,{highX,268}));graph->mouseDrag(mouse(*graph,{highX,244},true));graph->mouseUp(mouse(*graph,{highX,244}));check(std::abs(p.value("trim7")-2.51f)<.02f,"Resized graph routes high-band drag with scaled sensitivity");graph->mouseDoubleClick(mouse(*graph,{highX,268}));check(p.value("trim7")==0,"High-band trim independently resets");editor->setSize(740,450);tick();
    const char* ids[]{"amount","target","bypass","gillQuality"};for(int i=0;i<4;++i)check(p.apvts.getParameter(ids[i])->getParameterIndex()==i,"Legacy parameter index preserved");
    p.requestLearning(true);juce::Random random(213);juce::MidiBuffer midi;juce::AudioBuffer<float> b(2,256);for(int n=0;n<600;++n){for(int i=0;i<256;++i){const float v=.08f*(random.nextFloat()*2-1)+.06f*std::sin(float((n*256+i)*.105));b.setSample(0,i,v);b.setSample(1,i,v);}p.processBlock(b,midi);}p.requestLearning(false);p.processBlock(b,midi);check(p.savedProfile().valid&&p.balanceView().fine.enabled,"Learned spectrum is generated from native input audio");for(int n=0;n<30;++n)p.processBlock(b,midi);const double learnedGain=tone(p,800);check(std::abs(measuredResponse(p.balanceView(),800)-learnedGain)<.10,"Learned static, fine and dynamic cascade matches measured audio");tick();juce::FileOutputStream file(juce::File::getCurrentWorkingDirectory().getChildFile("GILLBALANCE-UI21-learned.png"));file.setPosition(0);file.truncate();juce::PNGImageFormat png;check(png.writeImageToStream(editor->createComponentSnapshot(editor->getLocalBounds()),file),"Native learned EQ screenshot captured");file.flush();editor->removeFromDesktop();if(failures)return 1;std::cout<<"BALANCE_NATIVE_UI21_PASS"<<std::endl;return 0;}
